function ConvertFrom-ToolchainToml {
    <# .SYNOPSIS Reads minSdk/targetSdk/compileSdk/buildTools/ndkVersion/agp from a React Native libs.versions.toml body. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$Text)
    $r = @{}
    foreach ($key in 'minSdk', 'targetSdk', 'compileSdk', 'buildTools', 'ndkVersion', 'agp') {
        if ($Text -match "(?m)^\s*$key\s*=\s*`"([^`"]+)`"") { $r[$key] = $Matches[1] }
    }
    return [pscustomobject]$r
}

function Get-AndroidProjectRequirements {
    <# .SYNOPSIS Reads the real project configuration: app id/version, SDK levels from installed React Native, Gradle wrapper version; enforces target >= 36 and compile >= 37. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    $app = (Get-Content -LiteralPath (Join-Path $Config.MobileRoot 'app.json') -Raw | ConvertFrom-Json).expo
    $tomlPath = Join-Path $Config.SourceRoot 'node_modules\react-native\gradle\libs.versions.toml'
    if (-not (Test-Path -LiteralPath $tomlPath)) { throw "React Native is not installed ($tomlPath missing). Run npm ci in the repository root (-InstallDependencies)." }
    $t = ConvertFrom-ToolchainToml -Text (Get-Content -LiteralPath $tomlPath -Raw)
    if ([int]$t.targetSdk -lt 36) { throw "targetSdk $($t.targetSdk) is below the required 36." }
    if ([int]$t.compileSdk -lt 37) { throw "compileSdk $($t.compileSdk) is below the required 37." }
    $gradle = $null
    $wrapper = Join-Path $Config.MobileRoot 'android\gradle\wrapper\gradle-wrapper.properties'
    if ((Test-Path -LiteralPath $wrapper) -and ((Get-Content -LiteralPath $wrapper -Raw) -match 'gradle-([\d.]+)-')) { $gradle = $Matches[1] }
    return [pscustomobject]@{
        PackageName = $app.android.package; VersionCode = [int]$app.android.versionCode; Version = $app.version
        MinSdk = [int]$t.minSdk; TargetSdk = [int]$t.targetSdk; CompileSdk = [int]$t.compileSdk
        BuildTools = $t.buildTools; Ndk = $t.ndkVersion; Agp = $t.agp; Gradle = $gradle
    }
}

function Get-JdkInfo {
    <# .SYNOPSIS Validates a JAVA_HOME as a stable (non-EA) JDK with javac/keytool/jarsigner and reports its major version. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$JdkHome)
    foreach ($tool in 'java.exe', 'javac.exe', 'keytool.exe', 'jarsigner.exe') { if (-not (Test-Path -LiteralPath (Join-Path $JdkHome "bin\$tool"))) { return $null } }
    $run = Invoke-Native -FilePath (Join-Path $JdkHome 'bin\java.exe') -Arguments @('-version') -AllowFailure
    $text = $run.Output -join ' '
    if ($text -notmatch 'version "(\d+)(?:\.(\d+))?') { return $null }
    $major = [int]$Matches[1]
    if ($major -eq 1) { $major = [int]$Matches[2] }
    return [pscustomobject]@{ Home = $JdkHome; Major = $major; EarlyAccess = ($text -match '-ea|-internal|-beta'); Text = $text }
}

function Find-Jdk {
    <# .SYNOPSIS Locates a stable LTS JDK (17, 21 or 25 -- the range Gradle 9 and AGP 9 support) from -JavaHome, JAVA_HOME or standard install folders. Generated Nov-01-2026. #>
    param([string]$JavaHome)
    $homes = @($JavaHome, $env:JAVA_HOME)
    foreach ($root in @("$env:ProgramFiles\Microsoft", "$env:ProgramFiles\Eclipse Adoptium", "$env:ProgramFiles\Java", "$env:ProgramFiles\Android\Android Studio\jbr")) {
        if (Test-Path -LiteralPath $root) { $homes += (Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | ForEach-Object FullName); $homes += $root }
    }
    $found = $homes | Where-Object { $_ } | Select-Object -Unique | ForEach-Object { Get-JdkInfo -JdkHome $_ } | Where-Object { $_ -and -not $_.EarlyAccess -and $_.Major -in @(17, 21, 25) }
    return ($found | Sort-Object { @(17, 21, 25).IndexOf($_.Major) } | Select-Object -First 1)
}

function Find-AndroidSdkRoot {
    <# .SYNOPSIS Returns the configured Android SDK root (parameter, ANDROID_HOME, ANDROID_SDK_ROOT or default per-user path). Generated Nov-01-2026. #>
    param([string]$SdkRoot)
    if ($SdkRoot) { return $SdkRoot }
    foreach ($c in @($env:ANDROID_HOME, $env:ANDROID_SDK_ROOT, (Join-Path $env:LOCALAPPDATA 'Android\Sdk'))) { if ($c -and (Test-Path -LiteralPath $c)) { return $c } }
    return (Join-Path $env:LOCALAPPDATA 'Android\Sdk')
}

function Get-AndroidSdkState {
    <# .SYNOPSIS Read-only check of SDK components required by the project (cmdline-tools, platform, build-tools, NDK, platform-tools, licenses). Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$SdkRoot, [Parameter(Mandatory)]$Requirements)
    $p = { param($rel) Test-Path -LiteralPath (Join-Path $SdkRoot $rel) }
    return [pscustomobject]@{
        SdkRoot = $SdkRoot
        CmdlineTools = (& $p 'cmdline-tools\latest\bin\sdkmanager.bat')
        PlatformTools = (& $p 'platform-tools\adb.exe')
        Platform = ((& $p "platforms\android-$($Requirements.CompileSdk)\android.jar") -or
            (& $p "platforms\android-$($Requirements.CompileSdk).0\android.jar"))
        BuildTools = (& $p "build-tools\$($Requirements.BuildTools)\apksigner.bat")
        Ndk = (& $p "ndk\$($Requirements.Ndk)")
        LicensesAccepted = (& $p 'licenses\android-sdk-license')
    }
}

function ConvertFrom-GoogleRepositoryXml {
    <# .SYNOPSIS Extracts the Windows cmdline-tools archive URL, size and SHA-1 from Google's repository2 XML metadata. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$XmlText)
    $xml = New-Object Xml.XmlDocument
    $xml.LoadXml($XmlText)
    $pkg = $xml.SelectSingleNode("//remotePackage[@path='cmdline-tools;latest']")
    if (-not $pkg) { throw 'cmdline-tools;latest not found in Google repository metadata.' }
    $archive = $pkg.SelectNodes('archives/archive') | Where-Object { $_.SelectSingleNode('host-os').InnerText -eq 'windows' } | Select-Object -First 1
    if (-not $archive) { throw 'No Windows archive for cmdline-tools in Google repository metadata.' }
    $checksum = $archive.SelectSingleNode('complete/checksum')
    return [pscustomobject]@{
        FileName = $archive.SelectSingleNode('complete/url').InnerText; Size = [int64]$archive.SelectSingleNode('complete/size').InnerText
        Hash = $checksum.InnerText; Algorithm = $checksum.GetAttribute('type').ToUpperInvariant()
    }
}

