function Install-AndroidToolsArchive {
    <# .SYNOPSIS Extracts verified tools in short SDK-local staging, validates Windows path limits and required files, and never publishes incomplete tools. #>
    param([Parameter(Mandatory)][string]$Zip, [Parameter(Mandatory)][string]$SdkRoot)
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $sdk = [IO.Path]::GetFullPath($SdkRoot)
    $target = Join-Path $sdk 'cmdline-tools\latest'
    if (Test-Path -LiteralPath $target) { throw "$target already exists; not overwriting." }
    $stage = Join-Path $sdk ('.gm-' + [guid]::NewGuid().ToString('N'))
    $archive = [IO.Compression.ZipFile]::OpenRead($Zip)
    try {
        foreach ($entry in $archive.Entries) {
            $relative = $entry.FullName.Replace('/', '\')
            $output = [IO.Path]::GetFullPath((Join-Path $stage $relative))
            if (-not $output.StartsWith($stage + '\', [StringComparison]::OrdinalIgnoreCase) -or
                -not $relative.StartsWith('cmdline-tools\', [StringComparison]::Ordinal)) {
                throw "Unexpected tools archive path: $($entry.FullName)"
            }
            $final = Join-Path $target $relative.Substring('cmdline-tools\'.Length)
            if ($output.Length -ge 260 -or $final.Length -ge 260) {
                throw 'Android archive paths exceed Windows PowerShell limits. Re-run with -AndroidSdkRoot C:\AndroidSdk.'
            }
        }
    } finally { $archive.Dispose() }
    New-Item -ItemType Directory -Force -Path $sdk | Out-Null
    New-Item -ItemType Directory -Path $stage -ErrorAction Stop | Out-Null
    try {
        [IO.Compression.ZipFile]::ExtractToDirectory($Zip, $stage)
        $tools = Join-Path $stage 'cmdline-tools'
        foreach ($required in @('bin\sdkmanager.bat', 'lib', 'source.properties')) {
            if (-not (Test-Path -LiteralPath (Join-Path $tools $required))) {
                throw "Incomplete Android tools archive: missing $required"
            }
        }
        New-Item -ItemType Directory -Force -Path (Split-Path $target) -ErrorAction Stop | Out-Null
        Move-Item -LiteralPath $tools -Destination $target -ErrorAction Stop
    } finally {
        Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction Stop
    }
}

function Install-AndroidCmdlineTools {
    <# .SYNOPSIS After approval, downloads Google's cmdline-tools zip, verifies Google-published size and checksum, and extracts it to SdkRoot\cmdline-tools\latest. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)][string]$SdkRoot)
    $repo = 'https://dl.google.com/android/repository'
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $meta = ConvertFrom-GoogleRepositoryXml -XmlText (Invoke-WebRequest -UseBasicParsing -Uri "$repo/repository2-3.xml").Content
    $detail = "Downloads $repo/$($meta.FileName) ($([math]::Round($meta.Size / 1MB)) MB), verifies Google's published $($meta.Algorithm) $($meta.Hash), extracts to $SdkRoot\cmdline-tools\latest."
    if (-not (Request-Approval -Action 'Install Android command-line tools' -Target $SdkRoot -Detail $detail)) { return $false }
    $zip = Save-VerifiedDownload -Url "$repo/$($meta.FileName)" -FileName $meta.FileName -ExpectedHash $meta.Hash -HashAlgorithm $meta.Algorithm
    if ((Get-Item -LiteralPath $zip).Length -ne $meta.Size) { throw 'Downloaded size differs from Google metadata.' }
    Install-AndroidToolsArchive -Zip $zip -SdkRoot $SdkRoot
    return $true
}

function Install-AndroidSdkPackages {
    <# .SYNOPSIS After approval, runs sdkmanager interactively so the operator personally reviews and accepts each license; nothing is auto-accepted. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)][string]$SdkRoot, [Parameter(Mandatory)]$Requirements, [Parameter(Mandatory)][string]$JavaHome)
    $sdkmanager = Join-Path $SdkRoot 'cmdline-tools\latest\bin\sdkmanager.bat'
    $platformVersion = [string]$Requirements.CompileSdk
    if ($Requirements.CompileSdk -ge 37) { $platformVersion += '.0' }
    $packages = @('platform-tools', "platforms;android-$platformVersion", "build-tools;$($Requirements.BuildTools)", "ndk;$($Requirements.Ndk)")
    if (-not (Request-Approval -Action 'Install Android SDK packages' -Target $SdkRoot -Detail "Packages: $($packages -join ', '). sdkmanager will display licenses; you must answer each prompt yourself.")) { return $false }
    Invoke-WithSecretEnv -Variables @{ JAVA_HOME = $JavaHome } -ScriptBlock {
        $quotedPackages = @($packages | ForEach-Object { '"' + $_ + '"' })
        Invoke-Native -FilePath $sdkmanager -Arguments (@("--sdk_root=$SdkRoot", '--install') + $quotedPackages) -Passthru | Out-Null
        if (-not (Test-Path -LiteralPath (Join-Path $SdkRoot 'licenses\android-sdk-license'))) {
            Invoke-Native -FilePath $sdkmanager -Arguments @("--sdk_root=$SdkRoot", '--licenses') -Passthru | Out-Null
        }
    }
    if (-not (Test-Path -LiteralPath (Join-Path $SdkRoot 'licenses\android-sdk-license'))) { throw 'Android SDK license was not accepted; the release build cannot proceed.' }
    $state = Get-AndroidSdkState -SdkRoot $SdkRoot -Requirements $Requirements
    $missing = @('PlatformTools', 'Platform', 'BuildTools', 'Ndk' | Where-Object { -not $state.$_ })
    if ($missing.Count) {
        throw "SDK installation did not provide required components: $($missing -join ', '). Do not start the release build; inspect sdkmanager output."
    }
    return $true
}

function Get-NormalizedFingerprint {
    <# .SYNOPSIS Extracts the first SHA-256 fingerprint from keytool/apksigner output as lowercase hex without separators. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$Text)
    if ($Text -match '(?i)SHA-?256(?: digest)?:\s*([0-9a-f:]{64,95})') { return ($Matches[1] -replace ':', '').ToLowerInvariant() }
    return $null
}

function Get-KeystoreFingerprint {
    <# .SYNOPSIS Reads the upload certificate SHA-256 and subject via keytool using -storepass:env (no password on the command line). Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$JavaHome, [Parameter(Mandatory)][string]$Keystore, [Parameter(Mandatory)][string]$Alias)
    $r = Invoke-Native -FilePath (Join-Path $JavaHome 'bin\keytool.exe') -Arguments @('-list', '-v', '-keystore', $Keystore, '-alias', $Alias, '-storepass:env', 'GARAGE_UPLOAD_STORE_PASSWORD')
    $text = $r.Output -join "`n"
    if ($text -match '(?m)^Owner:\s*(.+)$' -and $Matches[1] -match 'CN=Android Debug') { throw 'The selected keystore entry is the Android debug key; refusing.' }
    return Get-NormalizedFingerprint -Text $text
}

function Test-ReleaseArtifacts {
    <# .SYNOPSIS Verifies APK/AAB are non-empty and signed by the upload certificate (apksigner, jarsigner, keytool) and that the APK package/version/targetSdk match the project. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config, [Parameter(Mandatory)]$Requirements, [Parameter(Mandatory)][string]$JavaHome, [Parameter(Mandatory)][string]$SdkRoot,
          [Parameter(Mandatory)][string]$Apk, [Parameter(Mandatory)][string]$Aab, [Parameter(Mandatory)][string]$ExpectedFingerprint)
    foreach ($f in $Apk, $Aab) { if (-not (Test-Path -LiteralPath $f) -or (Get-Item -LiteralPath $f).Length -le 0) { throw "Missing or empty artifact: $f" } }
    $bt = Join-Path $SdkRoot "build-tools\$($Requirements.BuildTools)"
    $apk = Invoke-Native -FilePath (Join-Path $bt 'apksigner.bat') -Arguments @('verify', '--print-certs', '--verbose', $Apk)
    $apkText = $apk.Output -join "`n"
    if ($apkText -notmatch 'Verifies') { throw 'apksigner did not report a verified signature.' }
    if ((Get-NormalizedFingerprint -Text $apkText) -ne $ExpectedFingerprint) { throw 'APK signing certificate differs from the upload keystore certificate.' }
    if ($apkText -match 'CN=Android Debug') { throw 'APK is signed with the Android debug certificate.' }
    $jar = Invoke-Native -FilePath (Join-Path $JavaHome 'bin\jarsigner.exe') -Arguments @('-verify', $Aab) -AllowFailure
    if ($jar.ExitCode -ne 0 -or ($jar.Output -join ' ') -notmatch 'jar verified') { throw "jarsigner could not verify the AAB: $($jar.Output -join ' ')" }
    $cert = Invoke-Native -FilePath (Join-Path $JavaHome 'bin\keytool.exe') -Arguments @('-printcert', '-jarfile', $Aab)
    if ((Get-NormalizedFingerprint -Text ($cert.Output -join "`n")) -ne $ExpectedFingerprint) { throw 'AAB signing certificate differs from the upload keystore certificate.' }
    $manifest = (Invoke-Native -FilePath (Join-Path $bt 'aapt2.exe') -Arguments @('dump', 'xmltree', '--file', 'AndroidManifest.xml', $Apk)).Output -join "`n"
    if ($manifest -match 'android:debuggable[^\r\n]*=\(type 0x12\)0xffffffff|android:debuggable[^\r\n]*true') { throw 'APK manifest is debuggable.' }
    if ($manifest -match 'android:usesCleartextTraffic[^\r\n]*=\(type 0x12\)0xffffffff') { throw 'APK manifest allows cleartext traffic.' }
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $zip = [IO.Compression.ZipFile]::OpenRead($Aab)
    try {
        $entries = @($zip.Entries | ForEach-Object FullName)
        foreach ($required in 'base/manifest/AndroidManifest.xml', 'BundleConfig.pb') { if ($entries -notcontains $required) { throw "AAB is missing $required." } }
        if (-not ($entries | Where-Object { $_ -match '^META-INF/.+\.(RSA|DSA|EC)$' })) { throw 'AAB has no signature block file.' }
    } finally { $zip.Dispose() }
    $badging = (Invoke-Native -FilePath (Join-Path $bt 'aapt2.exe') -Arguments @('dump', 'badging', $Apk)).Output -join "`n"
    if ($badging -match 'application-debuggable') { throw 'APK reports application-debuggable.' }
    if ($badging -notmatch "package: name='$([regex]::Escape($Requirements.PackageName))' versionCode='$($Requirements.VersionCode)'") { throw 'APK package or versionCode does not match app.json.' }
    if ($badging -notmatch "targetSdkVersion:'(\d+)'" -or [int]$Matches[1] -lt 36) { throw 'APK targetSdkVersion is below 36.' }
    return $true
}

function Invoke-AndroidRelease {
    <# .SYNOPSIS After approval, runs Expo prebuild, then Gradle assembleRelease+bundleRelease with a signing init script, verifies the outputs and copies them with checksums to the output directory. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config, [Parameter(Mandatory)]$Requirements, [Parameter(Mandatory)][string]$JavaHome, [Parameter(Mandatory)][string]$SdkRoot,
          [Parameter(Mandatory)][string]$Keystore, [Parameter(Mandatory)][string]$Alias, [switch]$CleanPrebuild)
    $repoFull = [IO.Path]::GetFullPath($Config.SourceRoot).TrimEnd('\') + '\'
    if ([IO.Path]::GetFullPath($Keystore).StartsWith($repoFull, [StringComparison]::OrdinalIgnoreCase)) { throw 'The upload keystore must be stored outside the source repository.' }
    if (-not (Test-Path -LiteralPath $Keystore -PathType Leaf)) { throw "Upload keystore not found: $Keystore" }
    $apiUrl = $Config.ApiUrl
    if ($apiUrl -notmatch '^https://') { throw 'The release API URL must be HTTPS.' }
    $detail = "Prebuild + Gradle release for $($Requirements.PackageName) v$($Requirements.Version) ($($Requirements.VersionCode)); keystore $Keystore alias $Alias; API $apiUrl; output $($Config.OutputDirectory). No cloud upload."
    if (-not (Request-Approval -Action 'Build signed Android APK and AAB locally' -Target $Config.MobileRoot -Detail $detail -Required)) { return }
    $storePw = Read-SecretPrompt -Prompt 'Upload keystore password' -EnvironmentVariable 'GARAGE_UPLOAD_STORE_PASSWORD'
    $keyPw = Read-SecretPrompt -Prompt 'Upload key password' -EnvironmentVariable 'GARAGE_UPLOAD_KEY_PASSWORD'
    $nodeDir = Split-Path $Config.NodePath
    $buildEnv = @{
        JAVA_HOME = $JavaHome; ANDROID_HOME = $SdkRoot; ANDROID_SDK_ROOT = $SdkRoot; PATH = "$JavaHome\bin;$nodeDir;$env:PATH"
        CI = '1'; EXPO_NO_TELEMETRY = '1'; EXPO_PUBLIC_API_URL = $apiUrl
        GARAGE_UPLOAD_KEYSTORE_FILE = $Keystore; GARAGE_UPLOAD_KEY_ALIAS = $Alias
        GARAGE_UPLOAD_STORE_PASSWORD = $storePw; GARAGE_UPLOAD_KEY_PASSWORD = $keyPw
    }
    $script:releaseResult = $null
    Invoke-WithSecretEnv -Variables $buildEnv -ScriptBlock {
        $expected = Get-KeystoreFingerprint -JavaHome $JavaHome -Keystore $Keystore -Alias $Alias
        if (-not $expected) { throw 'Could not read the upload certificate fingerprint.' }
        if ($Config.ExpectedCertSha256 -and ($Config.ExpectedCertSha256 -replace '[:\s]', '').ToLowerInvariant() -ne $expected) { throw 'Keystore certificate does not match -ExpectedCertificateSha256.' }
        Write-Info "Upload certificate SHA-256: $expected"
        Push-Location -LiteralPath $Config.MobileRoot
        try {
            $prebuild = @('--no-install', 'expo', 'prebuild', '--platform', 'android')
            if ($CleanPrebuild) { $prebuild += '--clean' }
            Invoke-Native -FilePath (Join-Path $nodeDir 'npx.cmd') -Arguments $prebuild -Passthru | Out-Null
        } finally { Pop-Location }
        $android = Join-Path $Config.MobileRoot 'android'
        if (-not (Test-Path -LiteralPath (Join-Path $android 'gradlew.bat'))) { throw 'Expo prebuild did not generate android\gradlew.bat.' }
        $init = Join-Path $Config.ScriptRoot 'android-signing.init.gradle'
        Push-Location -LiteralPath $android
        try {
            Invoke-Native -FilePath '.\gradlew.bat' -Arguments @('--no-daemon', '--console=plain', '--init-script', $init, ':app:assembleRelease', ':app:bundleRelease') -Passthru | Out-Null
        } finally { Pop-Location }
        $apk = Join-Path $android 'app\build\outputs\apk\release\app-release.apk'
        $aab = Join-Path $android 'app\build\outputs\bundle\release\app-release.aab'
        Test-ReleaseArtifacts -Config $Config -Requirements $Requirements -JavaHome $JavaHome -SdkRoot $SdkRoot -Apk $apk -Aab $aab -ExpectedFingerprint $expected | Out-Null
        $out = Join-Path $Config.OutputDirectory (Get-Date -Format 'yyyyMMdd-HHmmss')
        New-Item -ItemType Directory -Force -Path $out | Out-Null
        $stem = "$($Requirements.PackageName)-$($Requirements.Version)-$($Requirements.VersionCode)"
        Copy-Item -LiteralPath $apk -Destination (Join-Path $out "$stem.apk")
        Copy-Item -LiteralPath $aab -Destination (Join-Path $out "$stem.aab")
        $hashes = Get-ChildItem -LiteralPath $out -File | ForEach-Object { "{0}  {1}" -f (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower(), $_.Name }
        Set-Content -LiteralPath (Join-Path $out 'SHA256SUMS.txt') -Value $hashes -Encoding ASCII
        Set-Content -LiteralPath (Join-Path $out 'build-info.json') -Encoding UTF8 -Value (@{ package = $Requirements.PackageName; versionCode = $Requirements.VersionCode; version = $Requirements.Version
            targetSdk = $Requirements.TargetSdk; compileSdk = $Requirements.CompileSdk; uploadCertSha256 = $expected; apiUrl = $apiUrl; builtAt = (Get-Date).ToString('o') } | ConvertTo-Json)
        $script:releaseResult = $out
    }
    Write-Info "Artifacts verified and written to $script:releaseResult"
    return $script:releaseResult
}
